# Simple propagation transform
def transform(grid):
    H, W = len(grid), len(grid[0])
    result = [[0]*W for _ in range(H)]

    # Horizontal propagation: each column propagates the last non-zero value
    for c in range(W):
        # Find last non-zero in this column
        for r in range(H):
            if grid[r][c] != 0:
                fill_val = grid[r][c]
                break

        # Fill the whole column with that value
        for r in range(H):
            result[r][c] = fill_val

    return result

